const PAIRS = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
];

export function toRoman(value) {
  if (typeof value !== 'number') throw new TypeError('value must be a number');
  if (!Number.isInteger(value) || value < 1 || value > 3999) {
    throw new RangeError('value must be an integer from 1 to 3999');
  }
  let left = value;
  let out = '';
  for (const [amount, letters] of PAIRS) {
    while (left >= amount) {
      out += letters;
      left -= amount;
    }
  }
  return out;
}

export function fromRoman(text) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  let at = 0;
  let total = 0;
  for (const [amount, letters] of PAIRS) {
    while (text.startsWith(letters, at)) {
      at += letters.length;
      total += amount;
    }
  }
  if (at !== text.length || total < 1 || total > 3999 || toRoman(total) !== text) {
    throw new SyntaxError(`${text} is not a standard Roman numeral`);
  }
  return total;
}
